// Products and rack layout, generated by scripts/build_app_data.py (never edit the JSON by hand).
import productsJson from "./generated/products.json";
import layoutJson from "./generated/layout.json";

export type Client = "Deccan" | "Matco" | "Praj";
export const CLIENTS: Client[] = ["Deccan", "Matco", "Praj"];

export interface Product {
  id: string;
  client: Client;
  brand: string;
  code: string;
  name: string;
  cat: string;
  size: string;
  units: number | null;
  perPallet: number | null;
  item: string | null;
}

export interface Face {
  id: string;
  rack: string;
  side: string;
  junction?: boolean;
  /** [column, [[level, bay], …]] */
  cols: [number, [number, number][]][];
}

export const PRODUCTS = productsJson as Product[];
export const FACES = (layoutJson as unknown as { faces: Face[] }).faces;
export const AREAS = (layoutJson as { areas: { id: string; name: string }[] }).areas;

const BY_ID = new Map(PRODUCTS.map(p => [p.id, p]));
export const productById = (id: string) => BY_ID.get(id);
export const findProduct = (client: Client, code: string) => PRODUCTS.find(p => p.client === client && p.code === code);

export const productLabel = (p: Product) => `${p.name}${p.size ? ` ${p.size}` : ""}${p.units ? ` × ${p.units}` : ""}`;

const hay = new Map(PRODUCTS.map(p => [p.id, `${p.code} ${p.name} ${p.brand} ${p.cat} ${p.size} ${p.client}`.toLowerCase()]));

/** Products matching every word typed. Exact code, then code prefix, then name prefix come first; the shipment's client next. */
export function searchProducts(query: string, client?: string, limit = 8): Product[] {
  const q = query.trim().toLowerCase();
  if (!q) return [];
  const words = q.split(/\s+/);
  const scored: [number, Product][] = [];
  for (const p of PRODUCTS) {
    if (!words.every(w => hay.get(p.id)!.includes(w))) continue;
    const code = p.code.toLowerCase(), name = p.name.toLowerCase();
    let s = code === q ? 0 : code.startsWith(q) ? 1 : name.startsWith(q) ? 2 : name.split(/\s+/).some(w => w.startsWith(words[0])) ? 3 : 4;
    if (client && p.client !== client) s += 5;
    if (/DONOTUSE|CROSSDOCK/i.test(p.item ?? "")) s += 3; // old or special codes sink below the normal product
    scored.push([s, p]);
  }
  scored.sort((a, b) => a[0] - b[0] || a[1].name.localeCompare(b[1].name) || a[1].code.localeCompare(b[1].code, undefined, { numeric: true }));
  return scored.slice(0, limit).map(x => x[1]);
}

// ---------- Slots ----------
export interface SlotMeta { code: string; face: string; rack: string; side: string; col: number; level: number; bay: number }
export const SLOTS: SlotMeta[] = FACES.flatMap(f =>
  f.cols.flatMap(([col, slots]) =>
    slots.map(([level, bay]) => ({ code: `${f.id}-${String(col).padStart(2, "0")}-L${level}-B${bay}`, face: f.id, rack: f.rack, side: f.side, col, level, bay })),
  ),
);
const SLOT_BY_CODE = new Map(SLOTS.map(s => [s.code, s]));
export const slotMeta = (code: string) => SLOT_BY_CODE.get(code);
export const isFloor = (code: string) => !SLOT_BY_CODE.has(code);
export const faceOf = (code: string) => SLOT_BY_CODE.get(code)?.face ?? code.replace(/-FLOOR-P\d+$/, "");

export function describeLocation(code: string): string {
  const m = SLOT_BY_CODE.get(code);
  if (m) return `${rackName(m.rack)}, side ${m.side} · column ${m.col} · level ${m.level} · bay ${m.bay}`;
  const f = code.match(/^(.+)-FLOOR-P(\d+)$/);
  if (f) return `Floor of ${f[1]} · spot ${Number(f[2])}`;
  return AREAS.find(a => code.startsWith(a.id))?.name ?? code;
}
export function rackName(rack: string) {
  if (rack === "D6") return "Door 6";
  if (rack.length > 2) return `Junction ${rack.slice(0, 2)}/${rack.slice(2)}`;
  return `Rack ${rack}`;
}
